def choose_move(observation):
    def clamp_step(v):
        if v > 1:
            return 1
        if v < -1:
            return -1
        return v

    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def as_point(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2 and is_num(x[0]) and is_num(x[1]):
            return [x[0], x[1]]
        return None

    def get_first(d, keys, default=None):
        if not isinstance(d, dict):
            return default
        for k in keys:
            if k in d:
                return d.get(k)
        return default

    def recurse_find_point(obj):
        p = as_point(obj)
        if p is not None:
            return p
        if isinstance(obj, dict):
            for v in obj.values():
                p = recurse_find_point(v)
                if p is not None:
                    return p
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                p = recurse_find_point(v)
                if p is not None:
                    return p
        return None

    def collect_points(obj, out):
        p = as_point(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for v in obj.values():
                collect_points(v, out)
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                collect_points(v, out)

    def dist2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    def sign(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    me = recurse_find_point(get_first(observation, ["position", "pos", "agent_pos", "self_pos", "location", "loc", "coordinates", "coord"], None))
    if me is None:
        me = recurse_find_point(observation)
    if me is None:
        return [0, 0]

    my_id = get_first(observation, ["player_id", "agent_id", "id", "self_id"], None)

    # Gather likely targets/resources/enemies
    resources = []
    for k in ["resources", "resource", "food", "targets", "target", "objectives", "objective", "collectibles", "collectible"]:
        collect_points(get_first(observation, [k], None), resources)

    enemies = []
    for k in ["enemies", "enemy", "opponents", "opponent", "hazards", "hazard", "threats", "threat"]:
        collect_points(get_first(observation, [k], None), enemies)

    allies = []
    for k in ["allies", "ally", "teammates", "teammate", "friends", "friend"]:
        collect_points(get_first(observation, [k], None), allies)

    # Detect map/territory if present
    territory = get_first(observation, ["territory", "grid", "map", "board", "ownership", "owner_map", "cells"], None)

    # Threat heuristic: flee if any enemy is close.
    if enemies:
        nearest_enemy = enemies[0]
        best_d = dist2(me, nearest_enemy)
        for p in enemies[1:]:
            d = dist2(me, p)
            if d < best_d:
                best_d = d
                nearest_enemy = p
        if best_d <= 16:
            dx = sign(me[0] - nearest_enemy[0])
            dy = sign(me[1] - nearest_enemy[1])
            if dx == 0 and dy == 0:
                dx = 1
            return [dx, dy]

    # Resource collection / generic objective chasing.
    if resources:
        nearest = resources[0]
        best_d = dist2(me, nearest)
        for p in resources[1:]:
            d = dist2(me, p)
            if d < best_d:
                best_d = d
                nearest = p
        return [clamp_step(sign(nearest[0] - me[0])), clamp_step(sign(nearest[1] - me[1]))]

    # Territory control: move toward the nearest non-self cell if we can infer one.
    if isinstance(territory, dict):
        # Look for explicit frontier/target cells.
        for k in ["frontier", "frontiers", "border", "borders", "targets", "target_cells", "open", "neutral", "unclaimed"]:
            pts = []
            collect_points(territory.get(k), pts)
            if pts:
                nearest = pts[0]
                best_d = dist2(me, nearest)
                for p in pts[1:]:
                    d = dist2(me, p)
                    if d < best_d:
                        best_d = d
                        nearest = p
                return [clamp_step(sign(nearest[0] - me[0])), clamp_step(sign(nearest[1] - me[1]))]

    if isinstance(territory, (list, tuple)) and territory:
        # If this is a grid, seek nearest cell that looks non-owned / interesting.
        candidates = []
        for y, row in enumerate(territory):
            if isinstance(row, (list, tuple)):
                for x, cell in enumerate(row):
                    interesting = False
                    if my_id is None:
                        if cell not in (None, 0, -1, ".", " ", False):
                            interesting = True
                    else:
                        if cell != my_id:
                            interesting = True
                    if interesting:
                        candidates.append([x, y])
        if candidates:
            nearest = candidates[0]
            best_d = dist2(me, nearest)
            for p in candidates[1:]:
                d = dist2(me, p)
                if d < best_d:
                    best_d = d
                    nearest = p
            return [clamp_step(sign(nearest[0] - me[0])), clamp_step(sign(nearest[1] - me[1]))]

    # If allies exist and enemies are absent, spread slightly toward center of ally cluster? otherwise roam.
    if allies:
        ax = 0
        ay = 0
        n = 0
        for p in allies:
            ax += p[0]
            ay += p[1]
            n += 1
        if n > 0:
            cx = ax / n
            cy = ay / n
            # Move away from crowd a bit to cover more space.
            dx = sign(me[0] - cx)
            dy = sign(me[1] - cy)
            if dx == 0 and dy == 0:
                dx = 1
            return [dx, dy]

    # Default: gentle drift toward origin / center-like point for stability.
    dx = sign(-me[0])
    dy = sign(-me[1])
    if dx == 0 and dy == 0:
        dx = 1
    return [dx, dy]

